private static ShaderInstance shader, additive;
private static boolean failed;

private DominionShader() {}

public static boolean isAvailable() {
    return shader != null && !failed;
}

public static void bind(float seconds) {
    if (shader == null && !failed) {
        try {
            shader = new ShaderInstance(
                    Minecraft.getInstance().getResourceManager(),
                    "godwand_dominion",
                    DefaultVertexFormat.POSITION_TEX_COLOR
            );
            additive = new ShaderInstance(
                    Minecraft.getInstance().getResourceManager(),
                    "godwand_dominion_add",
                    DefaultVertexFormat.POSITION_TEX_COLOR
            );
        } catch (Exception error) {
            failed = true;
            GodWandMod.LOGGER.warn("God Wand: Block Dominion custom shader unavailable, falling back to vanilla", error);
        }
    }
    if (shader == null) {
        RenderSystem.setShader(GameRenderer::getPositionTexColorShader);
        return;
    }
    shader.safeGetUniform("VfxTime").set(seconds);
    if (additive != null) additive.safeGetUniform("VfxTime").set(seconds);
    RenderSystem.setShader(() -> shader);
}

/** 1.20.1 core shaders set their own blend when applied: glow pass uses the additive twin. */
public static void layer(boolean add) {
    if (shader == null) {
        if (add) RenderSystem.blendFunc(com.mojang.blaze3d.platform.GlStateManager.SourceFactor.SRC_ALPHA, com.mojang.blaze3d.platform.GlStateManager.DestFactor.ONE);
        else RenderSystem.defaultBlendFunc();
        return;
    }
    ShaderInstance chosen = add && additive != null ? additive : shader;
    RenderSystem.setShader(() -> chosen);
}

public static void prewarm() {
    bind(0f);
    if (shader == null) return;
    var buffer = RenderHelper.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX_COLOR);
    for (int i = 0; i < 4; i++) {
        buffer.vertex(0, 0, 0).uv(0.5f, 2.5f).color(0, 0, 0, 0).endVertex();
    }
    RenderSystem.enableBlend();
    RenderSystem.defaultBlendFunc();
    RenderSystem.depthMask(false);
    try {
        RenderHelper.draw(buffer);
    } finally {
        RenderSystem.depthMask(true);
        RenderSystem.disableBlend();
    }
}

